def compare(node, factor, solnHistory, case):
    x0 = initialPosition(classSVQ.globalCoords, classSVQ.initialRotations, classSVQ.inputRotations)[node]
    loadX, dispX, loadZ, dispZ = results([case, np.unique(classSVQ.globalCoords)]) # type: ignore
    u = np.array([s[node, :3] for s in solnHistory]) - x0  # displacement history of the tracked node
    P = np.array(classSVQ.diagnostics['converged']['loadratioHistory']) * factor
    dX, dZ = -u[:, 0], u[:, 2]  # signs so that the model matches the reference axes (7.4: -X, +Z)
    t = np.linspace(0, len(P) - 1, 20 * (len(P) - 1) + 1)  # 20 sub-points per converged step
    mX, mZ, mP = np.interp(t, np.arange(len(P)), dX), np.interp(t, np.arange(len(P)), dZ), np.interp(t, np.arange(len(P)), P)
    errorDeflX = np.mean(np.min(np.hypot((dispX[:, None] - mX[None]) / np.abs(dispX).max(), (loadX[:, None] - mP[None]) / np.abs(loadX).max()), axis=1))
    errorDeflZ = np.mean(np.min(np.hypot((dispZ[:, None] - mZ[None]) / np.abs(dispZ).max(), (loadZ[:, None] - mP[None]) / np.abs(loadZ).max()), axis=1))
    return errorDeflX, errorDeflZ

